import{_ as t,o as n,c as i,a2 as s}from"./chunks/framework.CCtxZRER.js";const g=JSON.parse('{"title":"Pencatatan Stok","description":"Di mana saja barang dicatat (database, ERP, catatan manual rak, laporan) dan cara menjaga catatan tetap akurat.","frontmatter":{"title":"Pencatatan Stok","description":"Di mana saja barang dicatat (database, ERP, catatan manual rak, laporan) dan cara menjaga catatan tetap akurat.","status":"ditinjau","dasar":"materi presentasi Gudang Teknik dan catatan alur proses","diperbarui":"2026-10-13T00:00:00.000Z","kategori":"Gudang Teknik","sumber":["ppt-gudang-teknik","catatan-alur"],"kata_kunci":["administrasi","pencatatan stok","kontrol stok","master material","database","ERP","catatan manual rak","laporan OS/PPIC","stock opname","laporan stok","mutasi","saldo","akurasi stok","selisih"]},"headers":[],"relativePath":"divisi/administrasi-stok.md","filePath":"divisi/administrasi-stok.md"}'),r={name:"divisi/administrasi-stok.md"};function e(d,a,l,o,u,k){return n(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="pencatatan-stok" tabindex="-1">Pencatatan Stok <a class="header-anchor" href="#pencatatan-stok" aria-label="Permalink to &quot;Pencatatan Stok&quot;">​</a></h1><p class="lead">Catatan harus selalu sama dengan kondisi barang di rak. Kalau catatannya salah, gudang tidak bisa diandalkan.</p><h2 id="di-mana-saja-barang-dicatat" tabindex="-1">Di mana saja barang dicatat? <a class="header-anchor" href="#di-mana-saja-barang-dicatat" aria-label="Permalink to &quot;Di mana saja barang dicatat?&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Catatan</th><th>Isinya</th><th>Kapan diisi</th></tr></thead><tbody><tr><td data-label="Catatan"><strong>Database barang</strong></td><td data-label="Isinya">Jumlah, jenis barang, tipe barang, tanggal masuk, dan lokasi rak</td><td data-label="Kapan diisi">Saat barang masuk sudah diterima</td></tr><tr><td data-label="Catatan"><strong>ERP perusahaan</strong></td><td data-label="Isinya">Permintaan dari divisi lain dan laporan barang keluar</td><td data-label="Kapan diisi">Saat staff menyetujui permintaan</td></tr><tr><td data-label="Catatan"><strong>Catatan manual di rak</strong></td><td data-label="Isinya">Barang yang ditaruh atau diambil dari rak itu</td><td data-label="Kapan diisi">Setiap kali barang ditaruh atau diambil</td></tr><tr><td data-label="Catatan"><strong>Laporan ke OS/PPIC</strong></td><td data-label="Isinya">Barang sudah masuk dan sesuai</td><td data-label="Kapan diisi">Setelah input database</td></tr><tr><td data-label="Catatan"><strong>Stock opname</strong></td><td data-label="Isinya">Hasil hitung fisik dibandingkan dengan catatan</td><td data-label="Kapan diisi">Sesuai jadwal penghitungan</td></tr><tr><td data-label="Catatan"><strong>Laporan stok</strong></td><td data-label="Isinya">Saldo, mutasi, dan stok minimum</td><td data-label="Kapan diisi">Berkala, sebagai dasar keputusan</td></tr></tbody></table><p>Semua data mengacu pada <strong>master material</strong>, yaitu daftar induk berisi kode, nama, spesifikasi, satuan, dan lokasi setiap barang.</p><h2 id="rumus-dasar-stok" tabindex="-1">Rumus dasar stok <a class="header-anchor" href="#rumus-dasar-stok" aria-label="Permalink to &quot;Rumus dasar stok&quot;">​</a></h2><blockquote><p><strong>Stok akhir = stok awal + barang masuk − barang keluar</strong></p></blockquote><p>Kalau hasil hitung di rak berbeda dengan angka di catatan, berarti ada barang yang belum dicatat, salah catat, atau berpindah tanpa catatan.</p><h2 id="kebiasaan-baik" tabindex="-1">Kebiasaan baik <a class="header-anchor" href="#kebiasaan-baik" aria-label="Permalink to &quot;Kebiasaan baik&quot;">​</a></h2><ul><li><strong>Catat saat itu juga.</strong> Jangan menunda sampai akhir hari.</li><li><strong>Isi catatan manual di rak</strong> setiap kali menaruh atau mengambil barang.</li><li><strong>Pakai kode barang, bukan nama.</strong> Nama bisa ditulis berbeda-beda, kode tidak.</li><li><strong>Kembalikan barang ke rak yang benar</strong>, sesuai lokasi di database.</li><li><strong>Laporkan selisih, jangan mengubah angka sendiri.</strong> Perbaikan catatan harus disetujui.</li></ul><h2 id="mengukur-ketepatan-stok" tabindex="-1">Mengukur ketepatan stok <a class="header-anchor" href="#mengukur-ketepatan-stok" aria-label="Permalink to &quot;Mengukur ketepatan stok&quot;">​</a></h2><p>Salah satu ukuran gudang yang baik adalah <strong>stock accuracy</strong>: seberapa sama jumlah barang di rak dengan catatan.</p><blockquote><p><strong>Akurasi stok (%) = jumlah barang yang cocok ÷ jumlah barang yang dihitung × 100</strong></p></blockquote><p>Latihannya ada di <a href="/WareHouse/tutorial/hitung-fisik">Mencatat Hitung Fisik</a>.</p>',14)])])}const m=t(r,[["render",e]]);export{g as __pageData,m as default};
